import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class StdDateFormat_parse_TriageGen1Test {

    private StdDateFormat dateFormat;

    @Before
    public void setUp() {
        dateFormat = new StdDateFormat();
    }

    /**
     * Tests ISO8601 branch (e.g., "2023-10-27T10:00:00Z")
     */
    @Test
    public void testParse_ISO8601() {
        String isoDate = "2023-10-27T10:00:00Z";
        ParsePosition pos = new ParsePosition(0);
        Date result = dateFormat.parse(isoDate, pos);
        assertNotNull(result);
        assertEquals(0, pos.getIndex());
    }
















}

